      hu: ["Spanyol építészet", "Stratégiai kikötő", "20. században épült", "Partvédelem"],
      ro: ["Arhitectură spaniolă", "Port strategic", "Construit în sec. XX", "Apărarea coastei"],
      en: ["Spanish architecture", "Strategic harbor", "Built in 20th century", "Coastal defense"],
      es: ["Arquitectura española", "Puerto estratégico", "Construido en s. XX", "Defensa costera"],
